-- =============================================================================
-- 04  Identity and access control (tenant scope)
-- Spec refs: 6.1 (FR-001..FR-011), 6.11 (FR-163..FR-165), 10.2.1, 11.
-- Every tenant-owned table carries tenant_id NOT NULL and a composite
-- (tenant_id, <pk>) unique key so children reference parents with
-- tenant-consistent composite foreign keys: a row can never point at a parent
-- in another tenant (extension 2.2).
-- =============================================================================
CREATE TABLE IF NOT EXISTS iam.departments (
  tenant_id            uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  department_id        uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  code                 text NOT NULL CHECK (code ~ '^[A-Za-z0-9_-]{2,40}$'),
  name                 text NOT NULL,
  description          text,
  parent_department_id uuid,
  status               text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, department_id),
  UNIQUE (tenant_id, code),
  FOREIGN KEY (tenant_id, parent_department_id) REFERENCES iam.departments (tenant_id, department_id)
);

CREATE TABLE IF NOT EXISTS iam.users (
  tenant_id         uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  user_id           uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  account_id        uuid NOT NULL REFERENCES iam.user_accounts(account_id) ON DELETE RESTRICT,
  email             citext NOT NULL,
  display_name      text NOT NULL,
  user_type         text NOT NULL DEFAULT 'employee' CHECK (user_type IN ('employee', 'broker', 'agent', 'service')),
  department_id     uuid,
  business_unit     text,
  country           text,
  lines_of_business text[] NOT NULL DEFAULT '{}',   -- '*' = all lines
  jurisdictions     text[] NOT NULL DEFAULT '{}',   -- '*' = all jurisdictions
  clearance_rank    smallint NOT NULL DEFAULT 1 CHECK (clearance_rank BETWEEN 0 AND 3),
  status            text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
  last_active_at    timestamptz,
  created_by        uuid,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, user_id),
  UNIQUE (tenant_id, account_id),
  UNIQUE (tenant_id, email),
  FOREIGN KEY (tenant_id, department_id) REFERENCES iam.departments (tenant_id, department_id)
);

-- User-to-tenant membership: the trust anchor for tenant resolution.
CREATE TABLE IF NOT EXISTS iam.tenant_memberships (
  membership_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id     uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  account_id    uuid NOT NULL REFERENCES iam.user_accounts(account_id) ON DELETE RESTRICT,
  user_id       uuid NOT NULL,
  status        text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'revoked')),
  is_default    boolean NOT NULL DEFAULT false,
  created_by    uuid,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, account_id),
  FOREIGN KEY (tenant_id, user_id) REFERENCES iam.users (tenant_id, user_id)
);

CREATE TABLE IF NOT EXISTS iam.teams (
  tenant_id     uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  team_id       uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  department_id uuid NOT NULL,
  name          text NOT NULL,
  description   text,
  created_at    timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, team_id),
  UNIQUE (tenant_id, department_id, name),
  FOREIGN KEY (tenant_id, department_id) REFERENCES iam.departments (tenant_id, department_id)
);

CREATE TABLE IF NOT EXISTS iam.team_members (
  tenant_id uuid NOT NULL,
  team_id   uuid NOT NULL,
  user_id   uuid NOT NULL,
  added_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (team_id, user_id),
  FOREIGN KEY (tenant_id, team_id) REFERENCES iam.teams (tenant_id, team_id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, user_id) REFERENCES iam.users (tenant_id, user_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS iam.user_groups (
  tenant_id   uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  group_id    uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  name        text NOT NULL,
  description text,
  source      text NOT NULL DEFAULT 'platform' CHECK (source IN ('platform', 'idp')),
  external_id text,
  created_at  timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, group_id),
  UNIQUE (tenant_id, name)
);

CREATE TABLE IF NOT EXISTS iam.user_group_members (
  tenant_id  uuid NOT NULL,
  group_id   uuid NOT NULL,
  user_id    uuid NOT NULL,
  valid_from timestamptz NOT NULL DEFAULT now(),
  valid_to   timestamptz,
  added_by   uuid,
  PRIMARY KEY (group_id, user_id),
  FOREIGN KEY (tenant_id, group_id) REFERENCES iam.user_groups (tenant_id, group_id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, user_id)  REFERENCES iam.users (tenant_id, user_id) ON DELETE CASCADE,
  CHECK (valid_to IS NULL OR valid_to > valid_from)
);

-- Global permission catalogue: reference data, identical for every tenant,
-- contains no tenant information => no RLS (documented in database design).
CREATE TABLE IF NOT EXISTS iam.permissions (
  permission_code text PRIMARY KEY CHECK (permission_code ~ '^[a-z_]+(\.[a-z_]+)+$'),
  description     text NOT NULL,
  category        text NOT NULL,
  is_admin        boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS iam.roles (
  tenant_id      uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  role_id        uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  code           text NOT NULL CHECK (code ~ '^[a-z0-9_]{2,60}$'),
  name           text NOT NULL,
  description    text,
  is_system      boolean NOT NULL DEFAULT false,   -- protected from modification
  is_admin       boolean NOT NULL DEFAULT false,
  conflicts_with text[] NOT NULL DEFAULT '{}',     -- segregation of duties (FR-165)
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, role_id),
  UNIQUE (tenant_id, code)
);

CREATE TABLE IF NOT EXISTS iam.role_permissions (
  tenant_id       uuid NOT NULL,
  role_id         uuid NOT NULL,
  permission_code text NOT NULL REFERENCES iam.permissions(permission_code) ON DELETE CASCADE,
  PRIMARY KEY (role_id, permission_code),
  FOREIGN KEY (tenant_id, role_id) REFERENCES iam.roles (tenant_id, role_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS iam.user_roles (
  tenant_id  uuid NOT NULL,
  user_id    uuid NOT NULL,
  role_id    uuid NOT NULL,
  scope      jsonb NOT NULL DEFAULT '{}'::jsonb,
  granted_by uuid,
  valid_from timestamptz NOT NULL DEFAULT now(),
  valid_to   timestamptz,                         -- role expiry (FR-007)
  granted_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, role_id),
  FOREIGN KEY (tenant_id, user_id) REFERENCES iam.users (tenant_id, user_id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, role_id) REFERENCES iam.roles (tenant_id, role_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS iam.user_attributes (
  tenant_id uuid NOT NULL,
  user_id   uuid NOT NULL,
  key       text NOT NULL,
  value     text NOT NULL,
  PRIMARY KEY (user_id, key, value),
  FOREIGN KEY (tenant_id, user_id) REFERENCES iam.users (tenant_id, user_id) ON DELETE CASCADE
);

-- Sessions: one per login per active tenant.  Refresh tokens rotate within a
-- family; reuse of a rotated token revokes the whole family (token theft).
CREATE TABLE IF NOT EXISTS iam.sessions (
  session_id       uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id       uuid NOT NULL REFERENCES iam.user_accounts(account_id) ON DELETE CASCADE,
  tenant_id        uuid REFERENCES platform.tenants(tenant_id),
  created_at       timestamptz NOT NULL DEFAULT now(),
  last_seen_at     timestamptz NOT NULL DEFAULT now(),
  absolute_expires_at timestamptz NOT NULL,
  mfa_verified_at  timestamptz,
  auth_method      text NOT NULL DEFAULT 'password',
  ip               inet,
  user_agent       text,
  revoked_at       timestamptz,
  revoked_reason   text
);

CREATE TABLE IF NOT EXISTS iam.refresh_tokens (
  token_id    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id  uuid NOT NULL REFERENCES iam.sessions(session_id) ON DELETE CASCADE,
  token_hash  text NOT NULL UNIQUE,     -- SHA-256 of the opaque token; token itself never stored
  issued_at   timestamptz NOT NULL DEFAULT now(),
  expires_at  timestamptz NOT NULL,
  used_at     timestamptz,
  revoked_at  timestamptz
);

CREATE TABLE IF NOT EXISTS iam.login_events (
  event_id    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id  uuid REFERENCES iam.user_accounts(account_id) ON DELETE SET NULL,
  tenant_id   uuid,
  email_hash  text,
  success     boolean NOT NULL,
  reason      text,
  auth_method text,
  ip          inet,
  user_agent  text,
  occurred_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS iam.password_reset_tokens (
  token_hash text PRIMARY KEY,
  account_id uuid NOT NULL REFERENCES iam.user_accounts(account_id) ON DELETE CASCADE,
  requested_by uuid,
  expires_at timestamptz NOT NULL,
  used_at    timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);

DROP TRIGGER IF EXISTS trg_users_touch ON iam.users;
CREATE TRIGGER trg_users_touch BEFORE UPDATE ON iam.users FOR EACH ROW EXECUTE FUNCTION app.touch_updated_at();
DROP TRIGGER IF EXISTS trg_roles_touch ON iam.roles;
CREATE TRIGGER trg_roles_touch BEFORE UPDATE ON iam.roles FOR EACH ROW EXECUTE FUNCTION app.touch_updated_at();
DROP TRIGGER IF EXISTS trg_departments_touch ON iam.departments;
CREATE TRIGGER trg_departments_touch BEFORE UPDATE ON iam.departments FOR EACH ROW EXECUTE FUNCTION app.touch_updated_at();
DROP TRIGGER IF EXISTS trg_memberships_touch ON iam.tenant_memberships;
CREATE TRIGGER trg_memberships_touch BEFORE UPDATE ON iam.tenant_memberships FOR EACH ROW EXECUTE FUNCTION app.touch_updated_at();

-- Segregation-of-duties guard: a user may not hold two roles that conflict.
CREATE OR REPLACE FUNCTION iam.enforce_role_sod() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE conflict text;
BEGIN
  SELECT r2.code INTO conflict
    FROM iam.roles r_new
    JOIN iam.user_roles ur ON ur.user_id = NEW.user_id AND ur.role_id <> NEW.role_id
                          AND (ur.valid_to IS NULL OR ur.valid_to > now())
    JOIN iam.roles r2 ON r2.role_id = ur.role_id
   WHERE r_new.role_id = NEW.role_id
     AND (r2.code = ANY (r_new.conflicts_with) OR r_new.code = ANY (r2.conflicts_with))
   LIMIT 1;
  IF conflict IS NOT NULL THEN
    RAISE EXCEPTION 'segregation of duties violation: role conflicts with %', conflict
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS trg_user_roles_sod ON iam.user_roles;
CREATE TRIGGER trg_user_roles_sod BEFORE INSERT OR UPDATE ON iam.user_roles
  FOR EACH ROW EXECUTE FUNCTION iam.enforce_role_sod();

-- >>> 05_document_management.sql
-- =============================================================================
-- 05  Document management: collections, documents, versions, metadata,
--     access rules, pages, ingestion jobs and logs.
-- Spec refs: 6.3, 6.4, 6.16, 10.2.2, 10.2.3, FR-039/040/045/047/049/050/051,
-- FR-167, FR-249..FR-256.
-- Classification rank: public 0, internal 1, confidential 2, restricted 3.
-- =============================================================================
CREATE TABLE IF NOT EXISTS content.collections (
  tenant_id          uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  collection_id      uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  code               text NOT NULL CHECK (code ~ '^[a-z0-9][a-z0-9_-]{1,59}$'),
  name               text NOT NULL,
  description        text,
  department_id      uuid,
  owner_user_id      uuid,
  line_of_business   text,
  jurisdictions      text[] NOT NULL DEFAULT '{}',
  classification     text NOT NULL DEFAULT 'internal' CHECK (classification IN ('public', 'internal', 'confidential', 'restricted')),
  retention_days     integer CHECK (retention_days IS NULL OR retention_days > 0),
  auto_publish       boolean NOT NULL DEFAULT true,     -- false => owner approval before publication (FR-047/251)
  status             text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'archived')),
  created_by         uuid,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, collection_id),
  UNIQUE (tenant_id, code),
  FOREIGN KEY (tenant_id, department_id) REFERENCES iam.departments (tenant_id, department_id),
  FOREIGN KEY (tenant_id, owner_user_id) REFERENCES iam.users (tenant_id, user_id)
);

-- Collection-level entitlements; documents inherit them (plus their own rules).
-- principal_type 'everyone' => principal_id is NULL and maps to the tenant principal.
CREATE TABLE IF NOT EXISTS content.collection_access (
  tenant_id      uuid NOT NULL,
  access_id      uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  collection_id  uuid NOT NULL,
  principal_type text NOT NULL CHECK (principal_type IN ('user', 'group', 'role', 'department', 'team', 'everyone')),
  principal_id   uuid,
  effect         text NOT NULL DEFAULT 'allow' CHECK (effect IN ('allow', 'deny')),
  permission     text NOT NULL DEFAULT 'read' CHECK (permission IN ('read', 'write', 'manage')),
  granted_by     uuid,
  created_at     timestamptz NOT NULL DEFAULT now(),
  CHECK ((principal_type = 'everyone') = (principal_id IS NULL)),
  UNIQUE NULLS NOT DISTINCT (tenant_id, collection_id, principal_type, principal_id, effect, permission),
  FOREIGN KEY (tenant_id, collection_id) REFERENCES content.collections (tenant_id, collection_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS content.documents (
  tenant_id          uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  document_id        uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  collection_id      uuid NOT NULL,
  title              text NOT NULL,
  document_type      text NOT NULL DEFAULT 'other' CHECK (document_type IN
                       ('policy_wording', 'policy_schedule', 'endorsement', 'claims_manual', 'underwriting_guideline',
                        'product_brochure', 'regulatory_circular', 'sop', 'customer_communication',
                        'authority_matrix', 'faq', 'other')),
  classification_confidence real,
  insurance_line     text,          -- line of business (motor, home, health, life, ...)
  product            text,
  jurisdictions      text[] NOT NULL DEFAULT '{}',
  language           text NOT NULL DEFAULT 'english',
  classification     text NOT NULL DEFAULT 'internal' CHECK (classification IN ('public', 'internal', 'confidential', 'restricted')),
  classification_rank smallint NOT NULL DEFAULT 1 CHECK (classification_rank BETWEEN 0 AND 3),
  lifecycle_state    text NOT NULL DEFAULT 'draft' CHECK (lifecycle_state IN
                       ('draft', 'processing', 'in_review', 'approved', 'published', 'superseded', 'expired',
                        'archived', 'withdrawn', 'quarantined', 'failed')),
  owner_user_id      uuid,
  department_id      uuid,
  current_version_id uuid,
  legal_hold         boolean NOT NULL DEFAULT false,
  legally_privileged boolean NOT NULL DEFAULT false,
  source_system      text NOT NULL DEFAULT 'upload',
  source_ref         text,
  checksum_sha256    text,
  size_bytes         bigint NOT NULL DEFAULT 0,
  mime_type          text,
  effective_from     date,
  effective_to       date,
  review_due_at      date,
  retention_until    date,
  -- Effective access, denormalised from collection_access + document_access by
  -- app.refresh_document_acl() and copied to every chunk / embedding (FR-045, FR-112).
  allow_principals   uuid[] NOT NULL DEFAULT '{}',
  deny_principals    uuid[] NOT NULL DEFAULT '{}',
  acl_fingerprint    text,
  duplicate_of       uuid,
  created_by         uuid,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  deleted_at         timestamptz,
  UNIQUE (tenant_id, document_id),
  CHECK (effective_to IS NULL OR effective_from IS NULL OR effective_to >= effective_from),
  FOREIGN KEY (tenant_id, collection_id) REFERENCES content.collections (tenant_id, collection_id) ON DELETE RESTRICT,
  FOREIGN KEY (tenant_id, owner_user_id) REFERENCES iam.users (tenant_id, user_id),
  FOREIGN KEY (tenant_id, department_id) REFERENCES iam.departments (tenant_id, department_id),
  FOREIGN KEY (tenant_id, duplicate_of)  REFERENCES content.documents (tenant_id, document_id)
);
CREATE UNIQUE INDEX IF NOT EXISTS documents_source_ref_uq
  ON content.documents (tenant_id, source_system, source_ref) WHERE source_ref IS NOT NULL;

CREATE TABLE IF NOT EXISTS content.document_versions (
  tenant_id             uuid NOT NULL,
  version_id            uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  document_id           uuid NOT NULL,
  version_seq           integer NOT NULL CHECK (version_seq > 0),
  version_label         text,
  original_filename     text NOT NULL,
  storage_uri           text NOT NULL,   -- tenant-prefixed key, generated server side
  checksum_sha256       text NOT NULL CHECK (checksum_sha256 ~ '^[0-9a-f]{64}$'),
  size_bytes            bigint NOT NULL CHECK (size_bytes >= 0),
  mime_type             text NOT NULL,
  detected_format       text,
  effective_from        date,
  effective_to          date,
  supersedes_version_id uuid,
  state                 text NOT NULL DEFAULT 'uploaded' CHECK (state IN
                          ('uploaded', 'processing', 'indexed', 'published', 'superseded', 'withdrawn', 'failed', 'quarantined')),
  page_count            integer,
  parser                text,
  ocr_applied           boolean NOT NULL DEFAULT false,
  extraction_confidence real,
  chunker_version       text,
  embedding_model       text,
  embedding_dimensions  integer,
  created_by            uuid,
  created_at            timestamptz NOT NULL DEFAULT now(),
  published_at          timestamptz,
  withdrawn_at          timestamptz,
  UNIQUE (tenant_id, version_id),
  UNIQUE (document_id, version_seq),
  FOREIGN KEY (tenant_id, document_id) REFERENCES content.documents (tenant_id, document_id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, supersedes_version_id) REFERENCES content.document_versions (tenant_id, version_id)
);

ALTER TABLE content.documents DROP CONSTRAINT IF EXISTS documents_current_version_fk;
ALTER TABLE content.documents ADD CONSTRAINT documents_current_version_fk
  FOREIGN KEY (tenant_id, current_version_id) REFERENCES content.document_versions (tenant_id, version_id)
  DEFERRABLE INITIALLY DEFERRED;

-- Typed key/value metadata per version, incl. insurance metadata
-- (policy_number, claim_number, coverage_type, sum_insured, deductible,
-- waiting_period, exclusion, effective_date, expiration_date, jurisdiction ...).
CREATE TABLE IF NOT EXISTS content.document_metadata (
  tenant_id   uuid NOT NULL,
  version_id  uuid NOT NULL,
  key         text NOT NULL CHECK (key ~ '^[a-z][a-z0-9_]{1,60}$'),
  value       text NOT NULL,
  source      text NOT NULL DEFAULT 'extracted' CHECK (source IN ('extracted', 'user', 'source_system', 'steward', 'rule')),
  confidence  real,
  validated   boolean NOT NULL DEFAULT false,
  created_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (version_id, key, value),
  FOREIGN KEY (tenant_id, version_id) REFERENCES content.document_versions (tenant_id, version_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS content.document_access (
  tenant_id      uuid NOT NULL,
  access_id      uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  document_id    uuid NOT NULL,
  principal_type text NOT NULL CHECK (principal_type IN ('user', 'group', 'role', 'department', 'team', 'everyone')),
  principal_id   uuid,
  effect         text NOT NULL DEFAULT 'allow' CHECK (effect IN ('allow', 'deny')),
  origin         text NOT NULL DEFAULT 'platform_policy' CHECK (origin IN ('source_acl', 'platform_policy')),
  granted_by     uuid,
  synced_at      timestamptz NOT NULL DEFAULT now(),
  CHECK ((principal_type = 'everyone') = (principal_id IS NULL)),
  UNIQUE NULLS NOT DISTINCT (tenant_id, document_id, principal_type, principal_id, effect),
  FOREIGN KEY (tenant_id, document_id) REFERENCES content.documents (tenant_id, document_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS content.document_pages (
  tenant_id      uuid NOT NULL,
  page_id        uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  version_id     uuid NOT NULL,
  document_id    uuid NOT NULL,
  page_number    integer NOT NULL CHECK (page_number > 0),
  page_label     text,
  text           text NOT NULL DEFAULT '',
  extraction     text NOT NULL DEFAULT 'text' CHECK (extraction IN ('text', 'ocr', 'table', 'mixed')),
  ocr_confidence real,
  low_confidence boolean NOT NULL DEFAULT false,
  char_count     integer NOT NULL DEFAULT 0,
  UNIQUE (tenant_id, page_id),
  UNIQUE (version_id, page_number),
  FOREIGN KEY (tenant_id, version_id)  REFERENCES content.document_versions (tenant_id, version_id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, document_id) REFERENCES content.documents (tenant_id, document_id) ON DELETE CASCADE
);

-- Ingestion ------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ingest.ingestion_jobs (
  tenant_id       uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  job_id          uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  document_id     uuid,
  version_id      uuid,
  job_type        text NOT NULL DEFAULT 'ingest' CHECK (job_type IN ('ingest', 'reprocess', 'reindex', 'reembed', 'delete')),
  status          text NOT NULL DEFAULT 'queued' CHECK (status IN
                    ('queued', 'running', 'succeeded', 'failed', 'retrying', 'dead_letter', 'cancelled', 'deferred')),
  stage           text NOT NULL DEFAULT 'queued',
  attempt         integer NOT NULL DEFAULT 0,
  max_attempts    integer NOT NULL DEFAULT 5,
  priority        smallint NOT NULL DEFAULT 5,
  idempotency_key text NOT NULL,
  initiated_by    uuid,           -- tenant user id
  correlation_id  text,
  task_id         text,
  error_code      text,
  error_message   text,           -- never contains document content (spec 10.2.3)
  stats           jsonb NOT NULL DEFAULT '{}'::jsonb,
  queued_at       timestamptz NOT NULL DEFAULT now(),
  started_at      timestamptz,
  finished_at     timestamptz,
  next_retry_at   timestamptz,
  UNIQUE (tenant_id, job_id),
  UNIQUE (tenant_id, idempotency_key),
  FOREIGN KEY (tenant_id, document_id) REFERENCES content.documents (tenant_id, document_id) ON DELETE SET NULL (document_id),
  FOREIGN KEY (tenant_id, version_id)  REFERENCES content.document_versions (tenant_id, version_id) ON DELETE SET NULL (version_id)
);

CREATE TABLE IF NOT EXISTS ingest.ingestion_job_logs (
  tenant_id  uuid NOT NULL,
  log_id     uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  job_id     uuid NOT NULL,
  stage      text NOT NULL,
  level      text NOT NULL DEFAULT 'info' CHECK (level IN ('debug', 'info', 'warning', 'error')),
  message    text NOT NULL,
  detail     jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  FOREIGN KEY (tenant_id, job_id) REFERENCES ingest.ingestion_jobs (tenant_id, job_id) ON DELETE CASCADE
);

DROP TRIGGER IF EXISTS trg_documents_touch ON content.documents;
CREATE TRIGGER trg_documents_touch BEFORE UPDATE ON content.documents FOR EACH ROW EXECUTE FUNCTION app.touch_updated_at();
DROP TRIGGER IF EXISTS trg_collections_touch ON content.collections;
CREATE TRIGGER trg_collections_touch BEFORE UPDATE ON content.collections FOR EACH ROW EXECUTE FUNCTION app.touch_updated_at();

-- >>> 06_chunks_embeddings.sql
-- =============================================================================
-- 06  Document chunks and embeddings (pgvector) + effective-ACL propagation
-- Spec refs: 6.5, 6.6, 10.2.2 (#14, #15), 10.4, 10.6 rules 6-7, FR-041..FR-045,
-- FR-074, FR-078, FR-080, FR-081, FR-087, FR-112, NFR-112.
--
-- Embedding storage: the column type is the dimension-less `vector`, and one
-- partial HNSW expression index exists per supported dimension (see
-- 08_search_indexes.sql).  Queries cast both sides to vector(N) and filter on
-- `dimensions = N`, so tenants may use different embedding models while every
-- vector search still uses an ANN index and never mixes incompatible vectors.
-- =============================================================================
CREATE TABLE IF NOT EXISTS content.document_chunks (
  tenant_id           uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  chunk_id            uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  document_id         uuid NOT NULL,
  version_id          uuid NOT NULL,
  collection_id       uuid NOT NULL,
  parent_chunk_id     uuid,
  chunk_index         integer NOT NULL CHECK (chunk_index >= 0),
  chunk_type          text NOT NULL DEFAULT 'text' CHECK (chunk_type IN ('text', 'table', 'parent', 'child', 'definition', 'faq')),
  title               text,
  section_path        text,
  clause_ref          text,
  page_from           integer,
  page_to             integer,
  content             text NOT NULL,
  identifiers         text NOT NULL DEFAULT '',   -- extracted policy/claim/form/clause numbers (exact search)
  fts_config          regconfig NOT NULL DEFAULT 'english',
  content_tsv         tsvector GENERATED ALWAYS AS (
                        setweight(to_tsvector(fts_config, coalesce(title, '') || ' ' || coalesce(section_path, '')), 'A') ||
                        setweight(to_tsvector('simple'::regconfig, identifiers), 'A') ||
                        setweight(to_tsvector(fts_config, content), 'B')) STORED,
  token_count         integer NOT NULL DEFAULT 0,
  content_hash        text NOT NULL,
  low_confidence      boolean NOT NULL DEFAULT false,     -- OCR below threshold (FR-066)
  injection_flag      boolean NOT NULL DEFAULT false,     -- instruction-like content detected (FR-136)
  sensitivity_tags    text[] NOT NULL DEFAULT '{}',       -- pii, health, financial ... (FR-237)
  -- denormalised filter / access attributes (no joins on the retrieval path)
  document_type       text NOT NULL DEFAULT 'other',
  line_of_business    text,
  product             text,
  jurisdictions       text[] NOT NULL DEFAULT '{}',
  classification_rank smallint NOT NULL DEFAULT 1,
  lifecycle_state     text NOT NULL DEFAULT 'processing',
  effective_from      date,
  effective_to        date,
  allow_principals    uuid[] NOT NULL DEFAULT '{}',
  deny_principals     uuid[] NOT NULL DEFAULT '{}',
  acl_fingerprint     text,
  lineage             jsonb NOT NULL DEFAULT '{}'::jsonb,  -- parser, chunker, extraction method (NFR-112)
  created_at          timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, chunk_id),
  UNIQUE (version_id, chunk_index),
  FOREIGN KEY (tenant_id, document_id)     REFERENCES content.documents (tenant_id, document_id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, version_id)      REFERENCES content.document_versions (tenant_id, version_id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, collection_id)   REFERENCES content.collections (tenant_id, collection_id),
  FOREIGN KEY (tenant_id, parent_chunk_id) REFERENCES content.document_chunks (tenant_id, chunk_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS content.chunk_embeddings (
  tenant_id           uuid NOT NULL,
  embedding_id        uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  chunk_id            uuid NOT NULL,
  document_id         uuid NOT NULL,
  model_name          text NOT NULL,
  dimensions          integer NOT NULL CHECK (dimensions IN (256, 384, 512, 768, 1024, 1536, 3072)),
  index_generation    integer NOT NULL DEFAULT 1,
  is_active           boolean NOT NULL DEFAULT true,
  embedding           vector NOT NULL,
  -- copies of the access attributes so ANN search applies the same RLS predicate
  classification_rank smallint NOT NULL DEFAULT 1,
  line_of_business    text,
  jurisdictions       text[] NOT NULL DEFAULT '{}',
  lifecycle_state     text NOT NULL DEFAULT 'processing',
  allow_principals    uuid[] NOT NULL DEFAULT '{}',
  deny_principals     uuid[] NOT NULL DEFAULT '{}',
  created_at          timestamptz NOT NULL DEFAULT now(),
  CHECK (vector_dims(embedding) = dimensions),
  UNIQUE (chunk_id, model_name, index_generation),
  FOREIGN KEY (tenant_id, chunk_id)    REFERENCES content.document_chunks (tenant_id, chunk_id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, document_id) REFERENCES content.documents (tenant_id, document_id) ON DELETE CASCADE
);

-- -----------------------------------------------------------------------------
-- Effective access computation (FR-045, FR-101, FR-102, FR-112).
--   allow = document-level allow rules when the document has any, otherwise the
--           collection's read/write/manage allow rules (documents can narrow,
--           never silently widen, the collection default);
--   deny  = union of collection and document deny rules (deny overrides allow).
-- 'everyone' maps to the tenant principal (tenant_id), which every member of
-- the tenant carries in app.current_principals.
-- SECURITY DEFINER, owned by the NOLOGIN role rag_acl_fn whose only policies
-- are on the ACL columns' tables; FORCE RLS keeps the RESTRICTIVE tenant policy
-- in effect, so the function can only touch rows of the caller's tenant.  It
-- returns only a fingerprint (no content) and then copies the result and the document's filter attributes to every chunk
-- and embedding, so a chunk can never be more visible than its document.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION app.refresh_document_acl(p_document_id uuid) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE
  d content.documents%ROWTYPE;
  v_allow uuid[];
  v_deny  uuid[];
  v_fp    text;
BEGIN
  -- Narrow definer: only administrative / worker contexts may trigger propagation,
  -- the tenant boundary still comes from the caller's transaction-local context.
  IF app.current_tenant_id() IS NULL OR NOT app.mode_in('tenant_admin', 'worker', 'platform_provisioning') THEN
    RAISE EXCEPTION 'refresh_document_acl requires an administrative or worker tenant context'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO d FROM content.documents WHERE document_id = p_document_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'document % not found in current tenant context', p_document_id USING ERRCODE = 'no_data_found';
  END IF;

  IF EXISTS (SELECT 1 FROM content.document_access a WHERE a.document_id = d.document_id AND a.effect = 'allow') THEN
    SELECT COALESCE(array_agg(DISTINCT COALESCE(a.principal_id, d.tenant_id) ORDER BY COALESCE(a.principal_id, d.tenant_id)), '{}')
      INTO v_allow FROM content.document_access a WHERE a.document_id = d.document_id AND a.effect = 'allow';
  ELSE
    SELECT COALESCE(array_agg(DISTINCT COALESCE(c.principal_id, d.tenant_id) ORDER BY COALESCE(c.principal_id, d.tenant_id)), '{}')
      INTO v_allow FROM content.collection_access c WHERE c.collection_id = d.collection_id AND c.effect = 'allow';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT p ORDER BY p), '{}') INTO v_deny FROM (
      SELECT COALESCE(a.principal_id, d.tenant_id) AS p FROM content.document_access a
       WHERE a.document_id = d.document_id AND a.effect = 'deny'
      UNION
      SELECT COALESCE(c.principal_id, d.tenant_id) FROM content.collection_access c
       WHERE c.collection_id = d.collection_id AND c.effect = 'deny') s;

  v_fp := md5(array_to_string(v_allow, ',') || '|' || array_to_string(v_deny, ',') || '|' ||
              d.classification_rank || '|' || coalesce(d.insurance_line, '') || '|' ||
              array_to_string(d.jurisdictions, ',') || '|' || d.lifecycle_state);

  UPDATE content.documents SET allow_principals = v_allow, deny_principals = v_deny, acl_fingerprint = v_fp
   WHERE document_id = d.document_id;

  UPDATE content.document_chunks c
     SET allow_principals = v_allow, deny_principals = v_deny, acl_fingerprint = v_fp,
         classification_rank = d.classification_rank, line_of_business = d.insurance_line,
         jurisdictions = d.jurisdictions, document_type = d.document_type, product = d.product,
         effective_from = d.effective_from, effective_to = d.effective_to,
         lifecycle_state = CASE WHEN c.version_id = d.current_version_id THEN d.lifecycle_state
                                WHEN d.lifecycle_state IN ('published', 'superseded') AND EXISTS (
                                     SELECT 1 FROM content.document_versions v
                                      WHERE v.version_id = c.version_id AND v.state = 'superseded') THEN 'superseded'
                                WHEN d.lifecycle_state IN ('withdrawn', 'archived', 'expired') THEN d.lifecycle_state
                                ELSE 'processing' END
   WHERE c.document_id = d.document_id;

  UPDATE content.chunk_embeddings e
     SET allow_principals = c.allow_principals, deny_principals = c.deny_principals,
         classification_rank = c.classification_rank, line_of_business = c.line_of_business,
         jurisdictions = c.jurisdictions, lifecycle_state = c.lifecycle_state
    FROM content.document_chunks c
   WHERE c.chunk_id = e.chunk_id AND c.document_id = d.document_id;

  UPDATE platform.tenant_usage SET content_epoch = content_epoch + 1, updated_at = now()
   WHERE tenant_id = d.tenant_id;
  RETURN v_fp;
END $$;

COMMIT;
